/**
 * Original animal silhouettes for puzzle grids.
 *
 * Every animal is an original drawing made for this project, stored as an
 * SVG path (the outer contour of the silhouette, sampled as a smooth
 * polygon). The outlines are not copied from Neoformix or from any other
 * commercial word-search product. All geometry is original and released
 * with the rest of this app.
 */

export interface AnimalDef {
  key: string;
  label: string;
  /** Smallest N×N canvas that keeps the silhouette recognisable. */
  minSize: number;
  /** Theme / search aliases (lowercase). The label and key are matched too. */
  aliases: string[];
  /** Closed SVG path in authoring coordinates (profile silhouette). */
  path: string;
  /** Optional torso box in the same coordinates, used to sit a sudoku inside the body. */
  focus?: [number, number, number, number];
  /** Override the natural bounding-box aspect (width / height). */
  aspect?: number;
}

